private void createReservation(Context ctx) {
    try {
        var body = gson.fromJson(ctx.body(), Map.class);

        String roomNumberStr = String.valueOf(body.get("roomNumber"));
        String guestName = String.valueOf(body.get("guestName"));
        String guestEmail = String.valueOf(body.get("guestEmail"));
        String guestCpf = String.valueOf(body.get("guestCpf"));
        String checkInStr = String.valueOf(body.get("checkIn"));
        String checkOutStr = String.valueOf(body.get("checkOut"));
        String guestsStr = String.valueOf(body.get("guests"));
        String ratePlanStr = String.valueOf(body.get("ratePlan"));

        if (body == null || !body.containsKey("roomNumber") || !body.containsKey("guestName") ||
            !body.containsKey("guestEmail") || !body.containsKey("guestCpf") ||
            !body.containsKey("checkIn") || !body.containsKey("checkOut") ||
            !body.containsKey("guests") || !body.containsKey("ratePlan")) {
            error(ctx, 400, "INVALID_REQUEST", "Missing required fields");
            return;
        }

        try {
            int roomNumber = Integer.parseInt(roomNumberStr);
            LocalDate checkIn = LocalDate.parse(checkInStr);
            LocalDate checkOut = LocalDate.parse(checkOutStr);
            int guests = Integer.parseInt(guestsStr);
            RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);

            if (guests < 1) {
                error(ctx, 400, "INVALID_REQUEST", "At least one guest is required");
                return;
            }

            Optional<Object> room = Optional.ofNullable(roomService.getRoomByNumber(roomNumber).orElse(null));
            if (room.isEmpty()) {
                error(ctx, 404, "ROOM_NOT_FOUND", "Room does not exist");
                return;
            }

            if (guests > room.get().getClass().getMethod("getCapacity").invoke(room.get()) ||
                !roomService.getRoomByNumber(roomNumber).isPresent()) {
                var r = roomService.getRoomByNumber(roomNumber).get();
                if (guests > r.getCapacity()) {
                    error(ctx, 422, "CAPACITY_EXCEEDED", "Too many guests for this room");
                    return;
                }
            }

            if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
                error(ctx, 400, "INVALID_REQUEST", "Check-out must be after check-in");
                return;
            }

            // Check availability
            var existing = reservationService.getReservationsByRoomAndDate(roomNumber, checkIn);
            if (!existing.isEmpty()) {
                error(ctx, 409, "ROOM_UNAVAILABLE", "Room is unavailable for the requested dates");
                return;
            }

            Reservation reservation = reservationService.createReservation(
                    roomNumber, guestName, guestEmail, guestCpf,
                    checkIn, checkOut, guests, ratePlan
            );

            ctx.status(201);
            ctx.json(serializeReservation(reservation));
        } catch (NumberFormatException | IllegalArgumentException e) {
            error(ctx, 400, "INVALID_REQUEST", "Invalid request format");
        }
    } catch (JsonSyntaxException e) {
        error(ctx, 400, "INVALID_REQUEST", "Invalid JSON");
    }
}

