    private void getOccupancyReport(Context ctx) {
        try {
            String dateStr = ctx.queryParam("date");
            if (dateStr == null || dateStr.isEmpty()) {
                error(ctx, 400, "INVALID_REQUEST", "Missing date parameter");
                return;
            }

            LocalDate date = LocalDate.parse(dateStr);
            String report = reportService.generateOccupancyReport(date);
            ctx.contentType("text/csv; charset=utf-8");
            ctx.result(report);
        } catch (IllegalArgumentException e) {
            error(ctx, 400, "INVALID_REQUEST", "Invalid date format");
        }
    }

    private void getRevenueReport(Context ctx) {
        try {
            String monthStr = ctx.queryParam("month");
            if (monthStr == null || monthStr.isEmpty()) {
                error(ctx, 400, "INVALID_REQUEST", "Missing month parameter");
                return;
            }

            YearMonth month = YearMonth.parse(monthStr);
            String report = reportService.generateRevenueReport(month);
            ctx.contentType("text/csv; charset=utf-8");
            ctx.result(report);
        } catch (IllegalArgumentException e) {
            error(ctx, 400, "INVALID_REQUEST", "Invalid month format");
        }
    }

    private void error(Context ctx, int status, String code, String message) {
        ctx.status(status);
        ctx.json(Map.of(
                "error", code,
                "message", message
        ));
    }

    private Map<String, Object> serializeReservation(Reservation r) {
        return Map.ofEntries(
                Map.entry("id", r.getId()),
                Map.entry("roomNumber", r.getRoomNumber()),
                Map.entry("guestName", r.getGuestName()),
                Map.entry("guestEmail", r.getGuestEmail()),
                Map.entry("guestCpf", r.getGuestCpf()),
                Map.entry("checkIn", r.getCheckIn().toString()),
                Map.entry("checkOut", r.getCheckOut().toString()),
                Map.entry("guests", r.getGuests()),
                Map.entry("ratePlan", r.getRatePlan().toString()),
                Map.entry("nights", r.getNights()),
                Map.entry("subtotal", roundToTwoDecimals(r.getSubtotal())),
                Map.entry("discount", roundToTwoDecimals(r.getDiscount())),
                Map.entry("total", roundToTwoDecimals(r.getTotal())),
                Map.entry("status", r.getStatus().toString()),
                Map.entry("amountPaid", roundToTwoDecimals(r.getAmountPaid())),
                Map.entry("refund", r.getRefund() != null ? roundToTwoDecimals(r.getRefund()) : null)
        );
    }

    private Map<String, Object> serializeReceipt(Receipt r) {
        return Map.ofEntries(
                Map.entry("title", "Comprovante de reserva"),
                Map.entry("reservationId", r.getReservationId()),
                Map.entry("guestName", r.getGuestName()),
                Map.entry("guestCpf", r.getGuestCpf()),
                Map.entry("roomNumber", r.getRoomNumber()),
                Map.entry("roomType", r.getRoomType()),
                Map.entry("checkIn", r.getCheckIn().toString()),
                Map.entry("checkOut", r.getCheckOut().toString()),
                Map.entry("nights", r.getNights()),
                Map.entry("subtotal", roundToTwoDecimals(r.getSubtotal())),
                Map.entry("discount", roundToTwoDecimals(r.getDiscount())),
                Map.entry("total", roundToTwoDecimals(r.getTotal()))
        );
    }

    private double roundToTwoDecimals(BigDecimal value) {
        return value.setScale(2, java.math.RoundingMode.HALF_EVEN).doubleValue();
    }
